<script>
document.addEventListener("DOMContentLoaded", function () {
    const container = document.querySelector(".scrollHeaderSwiper");

    if (!container || typeof Swiper === "undefined") return;

    // Prevent duplicate initialization
    if (container.swiper) return;

    const wrapper = container.querySelector(".swiper-wrapper");
    if (!wrapper) return;

    const originalSlides = Array.from(
        wrapper.querySelectorAll(".swiper-slide")
    );

    if (originalSlides.length === 0) return;

    // Duplicate slides to make continuous looping possible
    const minSlides = 8;

    while (wrapper.querySelectorAll(".swiper-slide").length < minSlides) {
        originalSlides.forEach(function (slide) {
            wrapper.appendChild(slide.cloneNode(true));
        });
    }

    const headerSwiper = new Swiper(container, {
        slidesPerView: "auto",
        spaceBetween: 0,
        loop: true,
        loopAdditionalSlides: 8,
        speed: 6000,
        autoplay: {
            delay: 0,
            disableOnInteraction: false,
            pauseOnMouseEnter: false
        },
        allowTouchMove: false,
        freeMode: {
            enabled: true,
            momentum: false
        }
    });

    container.addEventListener("mouseenter", function () {
        headerSwiper.autoplay.stop();
    });

    container.addEventListener("mouseleave", function () {
        headerSwiper.autoplay.start();
    });
});
</script>

