    <!-- DROPDOWN -->
     <script>
   document.addEventListener("click", function (e) {

    /* ============================
       CLICK SELECTED BOX
    ============================ */

    const selected = e.target.closest(
        ".course-dropdown .select-selected"
    );

    if (selected) {

        e.preventDefault();
        e.stopPropagation();

        const dropdown = selected.closest(".course-dropdown");
        const options = dropdown.querySelector(".select-items");

        // Close other dropdowns
        document.querySelectorAll(
            ".course-dropdown .select-items"
        ).forEach(function (item) {

            if (item !== options) {
                item.classList.add("select-hide");
            }

        });

        document.querySelectorAll(
            ".course-dropdown .select-selected"
        ).forEach(function (item) {

            if (item !== selected) {
                item.classList.remove("active");
            }

        });

        // Toggle current dropdown
        options.classList.toggle("select-hide");
        selected.classList.toggle("active");

        return;
    }


    /* ============================
       CLICK COURSE OPTION
    ============================ */

    const option = e.target.closest(
        ".course-dropdown .select-items > div"
    );

    if (option) {

        e.preventDefault();
        e.stopPropagation();

        const dropdown = option.closest(".course-dropdown");

        const selected =
            dropdown.querySelector(".select-selected");

        const options =
            dropdown.querySelector(".select-items");

        const value =
            option.getAttribute("data-value");

        const text =
            option.textContent.trim();


        /* Update visible selected text */
        const textElement =
            selected.querySelector("span:first-child");

        if (textElement) {
            textElement.textContent = text;
        }


        /* Update hidden input */
        const hiddenInput =
            dropdown.querySelector("#courseInterested");

        if (hiddenInput) {
            hiddenInput.value = value;
        }


        /* Close */
        options.classList.add("select-hide");

        selected.classList.remove("active");

        return;
    }


    /* ============================
       CLICK OUTSIDE
    ============================ */

    if (!e.target.closest(".course-dropdown")) {

        document.querySelectorAll(
            ".course-dropdown .select-items"
        ).forEach(function (item) {

            item.classList.add("select-hide");

        });

        document.querySelectorAll(
            ".course-dropdown .select-selected"
        ).forEach(function (item) {

            item.classList.remove("active");

        });

    }

});
    </script>
    
    
</body>

</html>